-- Schema behind generator_metadata.json, the GeneratorMetadata fixture
-- shared with supabase_typegen of supabase-flutter. Both files are copies of
-- packages/supabase_typegen/test/fixtures/ there, whose
-- tool/regenerate_fixture.ts documents how to regenerate them; copy them
-- again rather than changing them here.

CREATE TYPE public.mood AS ENUM ('happy', 'very happy', 'sad');

CREATE TABLE public.authors (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL
);
ALTER TABLE public.authors ENABLE ROW LEVEL SECURITY;

CREATE TABLE public.books (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title text NOT NULL,
  author_id bigint NOT NULL REFERENCES public.authors (id),
  price numeric,
  rating double precision,
  in_print boolean NOT NULL DEFAULT true,
  mood public.mood,
  tags text[],
  page_counts integer[],
  metadata jsonb,
  cover_uuid uuid,
  cover_image bytea,
  published_on date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamp
);
ALTER TABLE public.books ENABLE ROW LEVEL SECURITY;
COMMENT ON TABLE public.books IS 'Books available in the library';
COMMENT ON COLUMN public.books.created_at IS 'When the row was created';

-- A read-only aggregating view: not auto-updatable, so it must generate no
-- insert or update surface.
CREATE VIEW public.author_stats AS
SELECT
  books.author_id,
  count(*) AS book_count
FROM public.books
GROUP BY books.author_id;
COMMENT ON VIEW public.author_stats IS 'Aggregated statistics per author';

-- An auto-updatable view with one computed, non-updatable column
-- (discounted_price), which must be read-only in the generated code.
CREATE VIEW public.book_prices AS
SELECT
  books.id,
  books.title,
  books.price,
  books.price * 0.9 AS discounted_price
FROM public.books;
COMMENT ON VIEW public.book_prices IS 'Prices per book, with the standard discount precomputed';

-- A materialized view: never insertable or updatable.
CREATE MATERIALIZED VIEW public.book_summaries AS
SELECT
  books.id,
  books.title,
  authors.name AS author_name
FROM public.books
JOIN public.authors ON authors.id = books.author_id;
COMMENT ON MATERIALIZED VIEW public.book_summaries IS 'Denormalized book and author names';

-- A join view made insertable only through an INSTEAD OF INSERT trigger:
-- not auto-updatable, so is_updatable is false, but is_insert_enabled is true
-- and its columns are writable.
CREATE VIEW public.book_submissions AS
SELECT
  books.title,
  authors.name AS author_name
FROM public.books
JOIN public.authors ON authors.id = books.author_id;

CREATE FUNCTION public.insert_book_submission() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO public.books (title, author_id)
  VALUES (
    NEW.title,
    (SELECT id FROM public.authors WHERE name = NEW.author_name)
  );
  RETURN NEW;
END;
$$;

CREATE TRIGGER book_submissions_insert
INSTEAD OF INSERT ON public.book_submissions
FOR EACH ROW EXECUTE FUNCTION public.insert_book_submission();

-- A second schema: its objects are generated with the schema as a name
-- prefix, a table named like public.books proves the prefixing, and the keys
-- of inventory.stock relate tables within the schema and across schemas.
CREATE SCHEMA inventory;

CREATE TYPE inventory.condition AS ENUM ('new', 'used');

CREATE TABLE inventory.books (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  isbn text NOT NULL
);

CREATE TABLE inventory.stock (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  book_id bigint NOT NULL REFERENCES public.books (id),
  copy_id bigint NOT NULL REFERENCES inventory.books (id),
  condition inventory.condition NOT NULL DEFAULT 'new',
  quantity integer NOT NULL DEFAULT 0
);
COMMENT ON TABLE inventory.stock IS 'Copies held per book';

-- Computed fields and computed relationships: functions whose only argument
-- is a relation's row type. PostgREST selects a scalar one like a column and
-- embeds a row- or set-returning one like a foreign table; none of them is
-- part of `select=*`.
CREATE FUNCTION public.title_upper(public.books) RETURNS text
LANGUAGE sql STABLE AS $$ SELECT upper($1.title); $$;

-- A named parameter and an enum return type: the function is matched by the
-- type of its argument, however the argument is spelled.
CREATE FUNCTION public.mood_or_default(book public.books) RETURNS public.mood
LANGUAGE sql STABLE AS $$ SELECT coalesce(book.mood, 'happy'::public.mood); $$;

-- A set-returning function is a to-many computed relationship...
CREATE FUNCTION public.recent_books(public.authors) RETURNS SETOF public.books
LANGUAGE sql STABLE AS $$
  SELECT * FROM public.books WHERE author_id = $1.id ORDER BY created_at DESC;
$$;

-- ...unless it is declared ROWS 1, which makes it to-one.
CREATE FUNCTION public.latest_book(public.authors)
RETURNS SETOF public.books ROWS 1
LANGUAGE sql STABLE AS $$
  SELECT * FROM public.books
  WHERE author_id = $1.id
  ORDER BY created_at DESC
  LIMIT 1;
$$;

-- Named like a column of the relation: PostgREST resolves `title` to the
-- column, so the function gets no member.
CREATE FUNCTION public.title(public.books) RETURNS text
LANGUAGE sql STABLE AS $$ SELECT 'shadowed'; $$;

-- A computed field on a view.
CREATE FUNCTION public.discount(public.book_prices) RETURNS numeric
LANGUAGE sql STABLE AS $$ SELECT $1.price - $1.discounted_price; $$;

-- Functions called through /rpc. A set of rows of a table, with a required
-- argument and defaulted ones, one of them an enum.
CREATE FUNCTION public.search_books(
  query text,
  mood public.mood DEFAULT NULL,
  max_price numeric DEFAULT NULL
) RETURNS SETOF public.books
LANGUAGE sql STABLE AS $$
  SELECT * FROM public.books
  WHERE books.title ILIKE '%' || query || '%'
    AND (search_books.mood IS NULL OR books.mood = search_books.mood)
    AND (max_price IS NULL OR books.price <= max_price);
$$;

-- A single row of a table.
CREATE FUNCTION public.book_by_id(book_id bigint) RETURNS public.books
LANGUAGE sql STABLE AS $$ SELECT * FROM public.books WHERE id = book_id; $$;

-- Rows of their own shape.
CREATE FUNCTION public.author_book_counts(min_books integer DEFAULT 0)
RETURNS TABLE (author_name text, book_count bigint)
LANGUAGE sql STABLE AS $$
  SELECT authors.name, count(books.id)
  FROM public.authors
  LEFT JOIN public.books ON books.author_id = authors.id
  GROUP BY authors.name
  HAVING count(books.id) >= min_books;
$$;

-- A scalar without arguments, and a set of scalars that need a conversion.
CREATE FUNCTION public.count_books() RETURNS bigint
LANGUAGE sql STABLE AS $$ SELECT count(*) FROM public.books; $$;

CREATE FUNCTION public.publication_dates(author_id bigint) RETURNS SETOF date
LANGUAGE sql STABLE AS $$
  SELECT published_on FROM public.books
  WHERE books.author_id = publication_dates.author_id;
$$;

-- No result, and a timestamp argument with a default.
CREATE FUNCTION public.touch_book(
  book_id bigint,
  touched_at timestamptz DEFAULT now()
) RETURNS void
LANGUAGE sql AS $$
  UPDATE public.books SET updated_at = touched_at WHERE id = book_id;
$$;

-- An array argument.
CREATE FUNCTION public.books_with_tags(tags text[]) RETURNS SETOF public.books
LANGUAGE sql STABLE AS $$
  SELECT * FROM public.books WHERE books.tags @> books_with_tags.tags;
$$;

-- Overloads PostgREST tells apart by their argument names.
CREATE FUNCTION public.books_of(author_id bigint) RETURNS SETOF public.books
LANGUAGE sql STABLE AS $$
  SELECT * FROM public.books WHERE books.author_id = books_of.author_id;
$$;

CREATE FUNCTION public.books_of(author_name text, max_price numeric)
RETURNS SETOF public.books
LANGUAGE sql STABLE AS $$
  SELECT books.* FROM public.books
  JOIN public.authors ON authors.id = books.author_id
  WHERE authors.name = author_name AND books.price <= max_price;
$$;

-- Overloads PostgREST cannot tell apart: the same argument name with
-- different types.
CREATE FUNCTION public.price_label(amount numeric) RETURNS text
LANGUAGE sql IMMUTABLE AS $$ SELECT amount::text; $$;

CREATE FUNCTION public.price_label(amount integer) RETURNS text
LANGUAGE sql IMMUTABLE AS $$ SELECT amount::text; $$;

-- A sole unnamed json parameter takes the whole request body.
CREATE FUNCTION public.echo(json) RETURNS json
LANGUAGE sql IMMUTABLE AS $$ SELECT $1; $$;

-- A function of the second schema.
CREATE FUNCTION inventory.restock(stock_id bigint, amount integer)
RETURNS integer
LANGUAGE sql AS $$
  UPDATE inventory.stock SET quantity = quantity + amount
  WHERE id = stock_id
  RETURNING quantity;
$$;

-- Tables of a schema that is not generated, exposed through views. PostgREST
-- derives the relationships of the views from the foreign keys of the tables
-- behind them, so the views relate to each other and to public.books, and
-- nothing of the restricted schema is generated. The schema sorts after
-- public, so the document lists the keys into its tables after those into
-- the views.
CREATE SCHEMA restricted;

CREATE TABLE restricted.reviews (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  book_id bigint NOT NULL REFERENCES public.books (id),
  body text NOT NULL
);

CREATE TABLE restricted.review_replies (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  review_id bigint NOT NULL REFERENCES restricted.reviews (id),
  body text NOT NULL
);

CREATE VIEW public.reviews AS SELECT * FROM restricted.reviews;

CREATE VIEW public.review_replies AS SELECT * FROM restricted.review_replies;

-- A view that reaches its table through a view of a schema on PostgREST's
-- extra search path, which is followed but not generated.
CREATE SCHEMA extra;

CREATE TABLE restricted.loans (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  book_id bigint NOT NULL REFERENCES public.books (id),
  due_on date NOT NULL
);

CREATE VIEW extra.loans AS SELECT * FROM restricted.loans;

CREATE VIEW public.loans AS SELECT * FROM extra.loans;

-- A text column limited to a list of values by a check constraint, generated
-- as an enum, and a jsonb column matched against a JSON Schema with
-- pg_jsonschema, generated as a type for the object. The fixture database
-- has no pg_jsonschema, so a stand-in for its function takes the schema.
CREATE SCHEMA extensions;

CREATE FUNCTION extensions.jsonb_matches_schema(schema json, instance jsonb)
RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$ SELECT true $$;

CREATE TABLE public.profiles (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  status text NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'suspended', 'on hold')),
  settings jsonb CHECK (extensions.jsonb_matches_schema('{
    "type": "object",
    "description": "Preferences the user picked.",
    "properties": {
      "theme": {"type": "string", "description": "The color scheme."},
      "font_size": {"type": "integer"},
      "notifications": {
        "type": "object",
        "properties": {
          "email": {"type": "boolean"},
          "digest": {"type": ["string", "null"]}
        },
        "required": ["email"]
      },
      "shortcuts": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "key": {"type": "string"},
            "action": {"type": "string"}
          },
          "required": ["key", "action"]
        }
      },
      "extra": {}
    },
    "required": ["theme"]
  }', settings))
);

-- RETURNS TABLE functions whose columns are known not to be NULL: one whose
-- BEGIN ATOMIC body reads NOT NULL columns, with one column on the nullable
-- side of an outer join, and one whose comment names them.
CREATE FUNCTION public.book_titles()
RETURNS TABLE (id bigint, title text, author_name text)
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT books.id, books.title, authors.name
  FROM public.books
  LEFT JOIN public.authors ON authors.id = books.author_id;
END;

CREATE FUNCTION public.profile_statuses()
RETURNS TABLE (id bigint, status text, settings jsonb)
LANGUAGE plpgsql STABLE AS $$
BEGIN
  RETURN QUERY SELECT profiles.id, profiles.status, profiles.settings
  FROM public.profiles;
END;
$$;
COMMENT ON FUNCTION public.profile_statuses() IS
  E'Every profile with its status.\n@notNull id, status';
